import assert from 'node:assert/strict';
import { test } from 'vitest';
import { parse as parseCsv } from 'csv-parse/sync';

import { ClassWizQR } from '../src/index.js';
import { array2Csv } from '../src/variable/T.js';

const commaSpreadsheetUrl = 'http://wes.casio.com/math/index.php?q=I-234F+U-000000000000+M-0D00A00000+S-000410100000100E1010B000A86B+T-';

test('CSV fields containing delimiters are quoted and escaped', () => {
  assert.equal(
    array2Csv([
      ['plain', '1,25', 'say "hello"', 'line\nbreak'],
      [undefined, null, 2],
    ]),
    'plain,"1,25","say ""hello""","line\nbreak"\n,,2',
  );
});

test('comma decimal spreadsheet CSV uses decimal points', () => {
  const spreadsheet = new ClassWizQR()
    .setUrl(commaSpreadsheetUrl)
    .getResult()
    .spreadsheet;
  const records = parseCsv(spreadsheet.csv);

  assert.match(spreadsheet.csv, /0\.\d+/);
  assert.doesNotMatch(spreadsheet.csv, /"0,\d+"/);
  assert.equal(records.length, 45);
  assert.ok(records.every(row => row.length === 5));
  assert.ok(records.flat().some(value => /^0\.\d+$/.test(value)));
});
